using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation values
        // and DateTime.UtcNow is non-deterministic — use a fixed value for seed data.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: Cosmos provider now uses "$type" instead of
        // "Discriminator" by default. For existing documents that already store
        // "Discriminator", you must explicitly configure the property name.
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasDiscriminator<string>("Discriminator");
        });
    }

    // EF Core 9 breaking change: Synchronous I/O on Cosmos is no longer supported.
    // All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.)
    public async Task<List<Product>> GetProductsAsync()
    {
        // WRONG (throws InvalidOperationException in EF Core 9):
        //   return Products.ToList();
        // CORRECT:
        return await Products.ToListAsync();
    }

    public async Task SaveProductAsync(Product product)
    {
        Products.Add(product);
        // WRONG: SaveChanges() — throws in EF Core 9 Cosmos provider
        // CORRECT:
        await SaveChangesAsync();
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

